/**
 * Structured representation of the parsed time.
 */
export interface TimeDetails {
  /** Input candidate trimmed of whitespaces. */
  normalized: string;
  /** Date representation of the converted input candidate. */
  date: Date;
  /**
   * Type of the given time, which can either be an ISO string
   * or a relative time expression (e.g. Last 30 minutes).
   */
  type: 'expression' | 'iso8601';
}

/**
 * Representation of a timeframe.
 */
export interface Timeframe {
  /** Lower boundary of the timeframe. */
  from: string;
  /** Upper boundary of the timeframe. */
  to: string;
  /** Timeframe details containing more information about the upper and lower boundaries of the timeframe. */
  details?: {
    /**
     * Lower boundary of the timeframe in detailed format.
     * Contains information about the from date in Date and normalized string format, as well as
     * the type of the given time, which can either be an ISO string
     * or a relative time expression (e.g. Last 30 minutes).
     */
    from: TimeDetails;
    /**
     * Upper boundary of the timeframe in detailed format.
     * Contains information about the to date in Date and normalized string format, as well as
     * the type of the given time, which can either be an ISO string
     * or a relative time expression (e.g. Last 30 minutes).
     */
    to: TimeDetails;
  };
}

/** @internal */
export type _TimeOffsetValue =
  | number
  | 'endOfDay'
  | 'startOfDay'
  // eslint-disable-next-line @typescript-eslint/ban-types
  | (string & {});

/**
 * Offset applied to a time in milliseconds or literals for end or start of the day.
 * @internal
 */
export type _TimeOffset =
  | _TimeOffsetValue
  | { from: _TimeOffsetValue; to: _TimeOffsetValue };

/**
 * Typeguard to see if time offset is simple, so not an object.
 * @internal
 */
export function _isSimpleTimeOffset(
  offset: _TimeOffset,
): offset is _TimeOffsetValue {
  return typeof offset !== 'object';
}

/**
 * The value of a part of a time frame.
 */
export interface TimeValue {
  /** The actual selected date as ISOString, equals the value in case of an 'iso8601'-type. */
  absoluteDate: string;
  /** The sanitized value. */
  value: string;
  /** Defines the type of the value. */
  type: 'expression' | 'iso8601';
}

export interface TimeframeV2 {
  /** Start of the time frame. */
  from: TimeValue;
  /** End of the time frame. */
  to: TimeValue;
}
